export type CareGuide = {
  slug: string; category: CategoryId; name: string; description: string; focus: string; audience: string; overview: string;
  recommendations: Record<DisciplineId, string[]>; urgent: string; contact: string; takeaways: string[]; references: Reference[];
  specialtySlug?: string; education?: TopicEducation;
}
type GuideInput = Omit<CareGuide, "recommendations" | "references"> & { care: [string, string, string, string, string, string]; sources: [string, string][]; extra?: Reference[] }
function guide(input: GuideInput): CareGuide {
  const { care, sources, extra = [], ...rest } = input
  return { ...rest, recommendations: Object.fromEntries(disciplines.map((d, i) => [d.id, care[i].split("|")])) as Record<DisciplineId, string[]>, references: [...sources.map(([title, path]) => medline(title, path)), ...extra] }
}

