export function getGuide(category: string, slug: string) {
  return careGuides.find(g => g.category === category && g.slug === slug)
}

// Additional topic-specific sources for the preparation and aftercare sections.
const additionalSources: Record<string, Reference[]> = {
  reumatologia: [medline("Metotrexato: seguridad y frecuencia de administración", "druginfo/meds/a682019-es.html")],
  hematologia: [medline("Tomar suplementos de hierro", "ency/article/007478.htm")],
  "cirugia-general": [medline("Alta tras hernia inguinal", "ency/patientinstructions/000274.htm")],
  neurocirugia: [medline("Alta tras cirugía de la columna vertebral", "ency/patientinstructions/000313.htm")],
  coloproctologia: [medline("Cambio de la bolsa de ostomía", "ency/patientinstructions/000204.htm")],
  ginecologia: [medline("Alta tras histerectomía abdominal", "ency/patientinstructions/000275.htm"), medline("Alta tras histerectomía laparoscópica", "ency/patientinstructions/000276.htm")],
  obstetricia: [{ title: "Signos y síntomas de advertencia de urgencia materna", organization: "Centros para el Control y la Prevención de Enfermedades (CDC)", url: "https://www.cdc.gov/hearher/es/maternal-warning-signs/index.html" }],
  oftalmologia: [medline("Extracción de cataratas", "ency/article/002957.htm")],
  "medicina-urgencias": [medline("Dolor torácico", "ency/article/003079.htm")],
}
for (const item of careGuides) item.references.push(...(additionalSources[item.slug] ?? []))

export const specialties = [...careGuides]
for (const item of specialties) item.education = originalEducation[item.slug]
careGuides.push(...createAdditionalGuides(specialties, disciplines.map(item => item.id)))
careGuides.push(...createExpandedGuides(specialties))
for (const item of careGuides) {
  for (const discipline of disciplines) {
    item.recommendations[discipline.id] = [...new Set([...item.recommendations[discipline.id], ...extraRecommendations[discipline.id]])]
  }
  if (!item.references.some(reference => reference.url === selfCareReference.url)) item.references.push(selfCareReference)
}

export function sectionReferences(guide: CareGuide, discipline: DisciplineId) {
  const extra = discipline === "farmacia" ? commonReferences[0] : discipline === "fisioterapia" ? commonReferences[1] : discipline === "psicologia" ? commonReferences[2] : undefined
  return extra ? [...guide.references, extra] : guide.references
}
